DROP INDEX IF EXISTS `workout_sessions_cycle_block_workout`;--> statement-breakpoint
UPDATE `workout_sessions` SET `pass` = `cycle_number`, `training_block_id` = COALESCE((SELECT `tb`.`id` FROM `training_blocks` `tb` WHERE `tb`.`program_id` = `workout_sessions`.`program_id` AND `tb`.`position` = `workout_sessions`.`block_number`), 'removed-' || `block_number`);--> statement-breakpoint
UPDATE `workout_sessions` SET `cycle_id` = COALESCE((SELECT `c`.`id` FROM `cycles` `c` WHERE `c`.`program_id` = `workout_sessions`.`program_id` ORDER BY (`c`.`status` = 'active') DESC, `c`.`number` DESC LIMIT 1), `cycle_id`);--> statement-breakpoint
UPDATE `cycles` SET `pass` = `number`, `current_block_id` = COALESCE((SELECT `tb`.`id` FROM `training_blocks` `tb` WHERE `tb`.`program_id` = `cycles`.`program_id` AND `tb`.`position` = `cycles`.`current_block_number`), (SELECT `tb`.`id` FROM `training_blocks` `tb` WHERE `tb`.`program_id` = `cycles`.`program_id` ORDER BY `tb`.`position` DESC LIMIT 1));--> statement-breakpoint
DELETE FROM `cycles` WHERE `id` <> (SELECT `c`.`id` FROM `cycles` `c` WHERE `c`.`program_id` = `cycles`.`program_id` ORDER BY (`c`.`status` = 'active') DESC, `c`.`number` DESC LIMIT 1);--> statement-breakpoint
INSERT INTO `cycles` (`id`, `program_id`, `number`, `status`, `current_block_number`, `started_at`, `ended_at`, `current_block_id`, `pass`) SELECT lower(hex(randomblob(16))), `p`.`id`, 1, 'active', 1, `p`.`created_at`, NULL, (SELECT `tb`.`id` FROM `training_blocks` `tb` WHERE `tb`.`program_id` = `p`.`id` ORDER BY `tb`.`position` ASC LIMIT 1), 1 FROM `programs` `p` WHERE NOT EXISTS (SELECT 1 FROM `cycles` `c` WHERE `c`.`program_id` = `p`.`id`);
